import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function escapeTextarea(value) {
  // Character references prevent HTML parsing from dropping an initial newline.
  return escapeHtml(value).replace(/\r/g, '&#13;').replace(/\n/g, '&#10;');
}

// Validate calendar days directly, without JavaScript Date's timezone or year coercion.
export function isValidDueDate(value) {
  if (value.length !== 10 || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= daysInMonth[month - 1];
}

// Normalize only for matching; saved names and titles remain unchanged.
function matchesSearch(value, query) {
  const normalize = text => text.replace(/[ \t]+/g, ' ')
    .replace(/[A-Z]/g, letter => letter.toLowerCase());
  return normalize(value).includes(normalize(query));
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    :root { font-family: system-ui, sans-serif; color: #172439; background: #f4f6fa; }
    body { margin: 0; }
    main { max-width: 720px; margin: 64px auto; padding: 28px; background: white; border-radius: 12px; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    input:not([type="checkbox"]), select, textarea { box-sizing: border-box; width: 100%; padding: 12px; border: 1px solid #718096; border-radius: 6px; font: inherit; }
    button { padding: 10px 16px; background: #2454bc; color: white; border: 0; border-radius: 6px; font: inherit; cursor: pointer; }
    button:disabled { background: #718096; cursor: not-allowed; }
    button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible { outline: 3px solid #e69619; outline-offset: 3px; }
    .create button { margin-top: 12px; }
    .projects { list-style: none; padding: 0; margin-top: 28px; }
    .project { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-top: 1px solid #dee4ee; }
    .project span { overflow-wrap: anywhere; min-width: 0; }
    .project form { flex-shrink: 0; }
    .task { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; padding: 16px 0; border-top: 1px solid #dee4ee; overflow-wrap: anywhere; }
    .task label { margin: 0; font-weight: 400; }
    .filter { margin-top: 24px; }
    [role="alert"] { color: #a51c25; }
    @media (max-width: 600px) { main { margin: 16px; padding: 20px; } }
  </style>
</head>
<body><main>${content}</main>
<script>
  document.querySelectorAll('[data-auto-submit]').forEach(control => {
    control.addEventListener('change', () => control.form.requestSubmit());
  });
</script>
</body>
</html>`;
}

export function createApplication(dbPath) {
  if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
  const db = new DatabaseSync(dbPath);
  db.exec(`CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  )`);
  db.exec(`PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id)`);
  // Upgrade databases created before archive support without changing IDs or tasks.
  if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
    db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  // Project defaults affect only subsequent task creation, never existing tasks.
  if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'default_priority')) {
    db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_priority IN ('Low', 'Normal', 'High'))");
  }
  // Backfill older tasks with Normal regardless of their project's default.
  if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
    db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
  }
  // Empty dates represent no due date for both migrated and newly created tasks.
  if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
    db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
  }
  // Notes are plain text; upgrading leaves every existing task field untouched.
  if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'notes')) {
    db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
  }
  // Keep the legacy order column to migrate existing databases without reordering.
  if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'task_order')) {
    db.exec('ALTER TABLE tasks ADD COLUMN task_order INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET task_order = id');
  }
  // Positions remain reserved even while a task belongs to another project.
  db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id),
    project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id)
  );
    CREATE INDEX IF NOT EXISTS task_positions_project_order ON task_positions(project_id, position);
    INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
      SELECT id, project_id, task_order FROM tasks;`);
  const priorities = ['Low', 'Normal', 'High'];
  const listTasks = db.prepare(`SELECT t.id, t.title, t.completed, t.priority, t.due_date, t.notes
    FROM tasks t JOIN task_positions p ON p.task_id = t.id AND p.project_id = t.project_id
    WHERE t.project_id = ? ORDER BY p.position, t.id`);
  const insertTask = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
  const rememberPosition = db.prepare(`INSERT INTO task_positions (task_id, project_id, position)
    SELECT ?, ?, COALESCE(MAX(position), 0) + 1 FROM task_positions WHERE project_id = ?
    ON CONFLICT(task_id, project_id) DO NOTHING`);
  const destinations = db.prepare('SELECT id, name FROM projects WHERE archived = 0 AND id != ? ORDER BY id');
  const moveTask = db.prepare('UPDATE tasks SET project_id = ? WHERE id = ? AND project_id = ?');

  // Ownership and position writes must either both commit or both roll back.
  function transaction(operation) {
    db.exec('BEGIN IMMEDIATE');
    try {
      const result = operation();
      db.exec('COMMIT');
      return result;
    } catch (error) {
      db.exec('ROLLBACK');
      throw error;
    }
  }

  const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
  const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
  const setTaskPriority = db.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
  const setTaskDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
  const setTaskNotes = db.prepare('UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?');
  const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
    COUNT(t.id) AS total, COALESCE(SUM(t.completed), 0) AS completed
    FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
    WHERE p.archived = ? GROUP BY p.id ORDER BY p.id`);
  const findProject = db.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?');
  const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
  const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');

  function projectList(error = '', name = '', filter = 'Active', search = '') {
    const projects = listProjects.all(filter === 'Archived' ? 1 : 0)
      .filter(project => matchesSearch(project.name, search));
    const listFields = `<input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="search" value="${escapeHtml(search)}">`;
    return page('Projects', `<h1>Workboard</h1>
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <form class="create" method="post" action="/projects">
        ${listFields}
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" value="${escapeHtml(name)}">
        <button type="submit">Create project</button>
      </form>
      <form class="filter" method="get" action="/">
        <input type="hidden" name="search" value="${escapeHtml(search)}">
        <label for="project-filter">Project filter</label>
        <select id="project-filter" name="filter" data-auto-submit>
          ${['Active', 'Archived'].map(value => `<option${filter === value ? ' selected' : ''}>${value}</option>`).join('')}
        </select>
      </form>
      <form class="filter" method="get" action="/">
        <input type="hidden" name="filter" value="${filter}">
        <label for="project-search">Project search</label>
        <input id="project-search" name="search" value="${escapeHtml(search)}">
        <button type="submit">Search projects</button>
      </form>
      <ul class="projects">${projects.map(project => `<li class="project" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed}/${project.total} completed</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
        <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}">
          ${listFields}
          <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
        </form>
      </li>`).join('')}</ul>`);
  }

  function projectPage(project, filter, priorityFilter = 'All', error = '', range = { from: '', through: '' }, search = '') {
    const eligibleDestinations = destinations.all(project.id);
    const moveDisabled = project.archived || eligibleDestinations.length === 0;
    const tasks = listTasks.all(project.id).filter(task =>
      (filter === 'All' || Boolean(task.completed) === (filter === 'Completed')) &&
      (priorityFilter === 'All' || task.priority === priorityFilter) &&
      matchesSearch(task.title, search) &&
      ((!range.from && !range.through) || (task.due_date &&
        (!range.from || task.due_date >= range.from) &&
        (!range.through || task.due_date <= range.through))));
    const filterFields = `<input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">`;
    const rangeFields = `<input type="hidden" name="rangeFrom" value="${range.from}">
      <input type="hidden" name="rangeThrough" value="${range.through}">`;
    const searchField = `<input type="hidden" name="search" value="${escapeHtml(search)}">`;
    const editFields = filterFields + rangeFields + searchField;
    return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
      <form method="get" action="/"><button type="submit">Projects</button></form>
      ${project.archived ? '<p>Archived project</p>' : ''}
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <form class="create" method="post" action="/projects/${project.id}/rename">
        ${editFields}
        <label for="new-project-name">New project name</label>
        <input id="new-project-name" name="name" value="${escapeHtml(project.name)}"${project.archived ? ' disabled' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
      </form>
      <form class="filter" method="post" action="/projects/${project.id}/default-priority">
        ${editFields}
        <label for="default-task-priority">Default task priority</label>
        <select id="default-task-priority" name="priority"${project.archived ? ' disabled' : ''} data-auto-submit>
          ${priorities.map(value => `<option${project.default_priority === value ? ' selected' : ''}>${value}</option>`).join('')}
        </select>
      </form>
      <form class="create" method="post" action="/projects/${project.id}/tasks">
        ${editFields}
        <label for="task-title">Task title</label>
        <input id="task-title" name="title">
        <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
      </form>
      <form class="filter" method="get" action="/projects/${project.id}">
